member.example:
The following example demonstrates how to use the MessageCloseEventArgs in a Closed event handler:

<SfMessage Closed="@OnMessageClosed">
    Your message content here
</SfMessage>

@code {
    private void OnMessageClosed(MessageCloseEventArgs args)
    {
        if (args.IsInteracted)
        {
            // User explicitly closed the message
            Console.WriteLine("Message was closed by user interaction");
        }
        else
        {
            // Message was closed automatically (e.g., timeout)
            Console.WriteLine("Message was closed automatically");
        }
    }
}

The below code example shows border customization of the Message component.

<SfMessage CssClass="custom">
   Conference Room no 01 / Building 135 10:00 AM - 10:30 AM
</SfMessage>
<style>
.custom {
    border-color: pink;
}
</style>

The below code example shows how to handle the Closed event.

<SfMessage ShowCloseIcon="true" Closed="OnMessageClosed">
    <p>Click the close icon to close this message.</p>
</SfMessage>

@code {
    private void OnMessageClosed(MessageCloseEventArgs args)
    {
        Console.WriteLine($"Message closed. IsInteracted: {args.IsInteracted}");
    }
}

In the below code example, Skeleton background color has been customized by using  property.


<SfSkeleton CssClass="customize-skeleton" Width="100px" Shape="SkeletonType.Circle"></SfSkeleton>
<style>
.e-skeleton.customize-skeleton {
    background-color: darkgray;
}
</style>

A simple ToastEvents configuration.

<SfToast>
    <ToastEvents OnOpen="@OnToastOpen" 
                 OnClose="@OnToastClose" 
                 OnClick="@OnToastClick" 
                 Opened="@OnToastOpened" 
                 Closed="@OnToastClosed" 
                 Created="@OnToastCreated" 
                 Destroyed="@OnToastDestroyed" />
</SfToast>

@code {
    private void OnToastOpen(ToastBeforeOpenArgs args) 
    {
        // Handle before toast opens
    }

    private void OnToastClick(ToastClickEventArgs args) 
    {
        // Handle toast click
    }
}

example.code:
var animationSettings = new ToastAnimationSettingsModel
{
    Show = new ToastAnimationsModel 
    { 
        Effect = ToastEffect.SlideTop, 
        Duration = 300,
        Easing = ToastEasing.EaseIn 
    },
    Hide = new ToastAnimationsModel 
    { 
        Effect = ToastEffect.SlideBottom, 
        Duration = 200,
        Easing = ToastEasing.EaseOut 
    }
};

var showAnimation = new ToastAnimationsModel
{
    Effect = ToastEffect.FadeZoom,
    Duration = 400,
    Easing = ToastEasing.EaseInOut
};

var toastModel = new ToastModel
{
    Title = "Success",
    Content = "Operation completed successfully",
    Icon = "e-icons e-success",
    CssClass = "custom-toast",
    Timeout = 4000,
    ShowProgressBar = true,
    Position = new ToastPosition { X = "Right", Y = "Top" }
};

var position = new ToastPositionModel
{
    X = "Right",
    Y = "Top"
};

// This will position the Toast at the top-right corner

member.example:
Creating a Toast with custom template:

var toastModel = new ToastShowModel
{
    ID = "toast-1",
    IsRendered = true,
    TitleTemplate = builder => builder.AddMarkupContent(0, "<strong>Success</strong>"),
    ChildContent = builder => builder.AddMarkupContent(0, "<p>Operation completed successfully!</p>")
};

Using ToastContentModel for managing multiple Toast notifications:

var contentModel = new ToastContentModel
{
    Model = new ToastShowModel { ID = "toast-1" },
    Index = 0
};

Configuring a Toast progress bar with 5-second duration:

var progressBar = new ToastProgressBar
{
    MaxHideTime = 5000.0, // 5 seconds in milliseconds
    HideEstimatedTimeOfArrival = 3000.0 // 3 seconds remaining
};

example.code:
@ref="toastElement"
<SfToast @ref="toastObj">
    <ToastPosition X="Right" Y="Top"></ToastPosition>
</SfToast>

@code {
    SfToast toastObj;
    ElementReference toastElement;

    private async Task HideSpecificToast()
    {
        await toastObj.HideAsync(toastElement);
    }
}
